const FREQUENCY_BAND_MAP = new Map<string, number>()
for (const [band, words] of Object.entries(BAND_WORDS)) {
  const b = Number(band)
  for (const w of words) FREQUENCY_BAND_MAP.set(w, b)
}

/** Frequency band 1..7 (lower = more frequent/easier), or null if not in the top-50000 general-corpus list. */
export function getWordFrequencyBand(word: string): number | null {
  return FREQUENCY_BAND_MAP.get(word) ?? null
}

export { FREQUENCY_BAND_MAP }
